using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class SaveMotoroller {public static string Main(){var scooter=Object.FindFirstObjectByType<MotorollerController>();Undo.RecordObject(scooter.Movement.cargoSlots[0],"Raise scooter cargo anchor");scooter.Movement.cargoSlots[0].localPosition=new Vector3(0,1.05f,-.64f);PrefabUtility.ApplyPrefabInstance(scooter.gameObject,InteractionMode.AutomatedAction);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scooter.gameObject.scene);EditorSceneManager.SaveScene(scooter.gameObject.scene);return "Saved cargo anchor and controller configuration";}}
